"""Read-only graphical M9 second-person transfer laboratory."""

from __future__ import annotations

from html import escape
import json
from pathlib import Path


ROOT=Path(__file__).resolve().parent; RESULT_PATH=ROOT/"analysis/m9_1_second_person_transfer_summary_alias_result.json"; DATASET_PATH=ROOT/"datasets/m9_second_person_mira_synthetic_fixture_v1.json"; DEFAULT_TRANSFER_CUTOFF="E1"
TRANSFER={"REN_ZERO_SHOT":("REN 0-SHOT","#94a3b8"),"MIRA_PARAMETER_SWAP":("PARAM SWAP","#fbbf24"),"MIRA_FULL_ADAPTATION":("FULL ADAPT","#34d399")}; BASELINES={"B4_FULL_HISTORY_SUMMARY":("B4","#60a5fa"),"B5_STRUCTURED_HISTORY":("B5","#22d3ee")}

TRANSFER_LAB_CSS=r"""
.tr-lab{overflow:hidden;border:1px solid rgba(167,139,250,.28);border-radius:24px;color:#e2e8f0;background:radial-gradient(circle at 6% 0%,rgba(167,139,250,.17),transparent 34%),radial-gradient(circle at 96% 3%,rgba(34,211,238,.12),transparent 30%),#050914;box-shadow:0 30px 90px rgba(2,6,23,.5)}.tr-lab *{box-sizing:border-box}.tr-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:20px;align-items:center;padding:25px 28px 20px;border-bottom:1px solid rgba(148,163,184,.13)}.tr-kicker{color:#c4b5fd;font-size:10px;font-weight:900;letter-spacing:.16em}.tr-title{margin:6px 0 0;color:#f8fafc;font-size:clamp(23px,3vw,38px);line-height:1.08}.tr-sub{max-width:930px;margin:9px 0 0;color:#94a3b8;font-size:11px;line-height:1.55}.tr-stamps{display:grid;gap:7px;min-width:255px}.tr-stamp{border:1px solid rgba(251,113,133,.35);border-radius:13px;padding:10px 13px;background:rgba(127,29,29,.15);text-align:right}.tr-stamp.ok{border-color:rgba(52,211,153,.34);background:rgba(6,78,59,.17)}.tr-stamp b{display:block;color:#fecdd3;font-size:13px}.tr-stamp.ok b{color:#a7f3d0}.tr-stamp span{display:block;margin-top:3px;color:#64748b;font-size:8px}.tr-body{padding:20px 24px 26px}.tr-flow{display:grid;grid-template-columns:1fr 38px 1fr 38px 1fr;gap:8px;align-items:center}.tr-node{min-height:125px;border:1px solid rgba(148,163,184,.16);border-top:4px solid var(--tone);border-radius:14px;padding:13px;background:rgba(15,23,42,.72)}.tr-node b{color:var(--tone);font-size:9px}.tr-node strong{display:block;margin-top:8px;color:#f8fafc;font-size:22px}.tr-node span{display:block;margin-top:6px;color:#94a3b8;font-size:8px;line-height:1.45}.tr-arrow{color:#64748b;text-align:center;font-size:22px}.tr-label{margin:17px 3px 9px;color:#64748b;font-size:9px;font-weight:850;letter-spacing:.12em}.tr-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.tr-panel{border:1px solid rgba(148,163,184,.15);border-radius:14px;padding:12px;background:rgba(15,23,42,.66)}.tr-baselines{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.tr-base{border-radius:11px;padding:11px;background:#08101f;border-top:3px solid var(--tone)}.tr-base b{color:var(--tone);font-size:9px}.tr-base strong{display:block;margin-top:6px;color:#f8fafc;font-size:18px}.tr-base span{display:block;margin-top:4px;color:#64748b;font-size:7px}.tr-roll{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.tr-cut{border-radius:10px;padding:9px;background:#08101f;border-top:3px solid var(--tone)}.tr-cut b{color:var(--tone);font-size:8px}.tr-cut strong{display:block;margin-top:5px;color:#f8fafc;font-size:15px}.tr-cut span{display:block;margin-top:3px;color:#64748b;font-size:6px}.tr-cases{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.tr-case{border:1px solid rgba(148,163,184,.15);border-radius:13px;padding:10px;background:#08101f}.tr-case b{font-size:8px}.tr-case p{height:40px;overflow:hidden;color:#64748b;font-size:7px;line-height:1.35}.tr-lane{display:grid;grid-template-columns:58px 1fr 22px;gap:4px;margin-top:5px}.tr-lane label{color:var(--tone);font-size:6px;font-weight:850}.tr-lane span{overflow:hidden;text-overflow:ellipsis;color:#94a3b8;font-size:6px;white-space:nowrap}.tr-lane em{font-size:7px;font-style:normal}.tr-lane.ok em{color:#86efac}.tr-lane.fail em{color:#fda4af}.tr-core{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}.tr-core div{border:1px solid rgba(52,211,153,.22);border-radius:9px;padding:8px;background:rgba(6,78,59,.16)}.tr-core b{display:block;color:#86efac;font-size:7px}.tr-core span{display:block;margin-top:3px;color:#64748b;font-size:6px}.tr-boundary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:15px}.tr-boundary div{border-radius:12px;padding:12px;background:#08101f;border-top:3px solid var(--tone)}.tr-boundary b{display:block;color:var(--tone);font-size:9px}.tr-boundary span{display:block;margin-top:6px;color:#94a3b8;font-size:8px;line-height:1.48}
@media(max-width:1000px){.tr-flow{grid-template-columns:1fr}.tr-arrow{transform:rotate(90deg)}.tr-grid{grid-template-columns:1fr}.tr-cases{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.tr-hero{grid-template-columns:1fr;padding:20px 16px}.tr-stamp{text-align:left}.tr-body{padding:16px}.tr-baselines,.tr-roll,.tr-cases,.tr-core,.tr-boundary{grid-template-columns:1fr}}
"""


def _load(): return json.loads(RESULT_PATH.read_text()),json.loads(DATASET_PATH.read_text())
def transfer_cutoff_choices(): return [(f'{x} · Mira sealed future',x) for x in ("E1","E2","E3","E4")]
def _text(x): return escape(str(x))
def _pred(row): return row.get("selected_behavior") or max(row["probabilities"],key=row["probabilities"].get)


def _cases(result,dataset,cutoff):
    ids=next(x["test_event_ids"] for x in dataset["rolling_cutoffs"] if x["cutoff_id"]==cutoff); texts={x["event_id"]:x["observable_text"] for x in dataset["events"]}; cards=[]
    order=("B4_FULL_HISTORY_SUMMARY","B5_STRUCTURED_HISTORY","REN_ZERO_SHOT","MIRA_PARAMETER_SWAP","MIRA_FULL_ADAPTATION")
    colors={**BASELINES,**TRANSFER}
    for sample in ids:
        lanes=[]
        for condition in order:
            row=next(x for x in result["rows"] if x["sample_id"]==sample and x["condition"]==condition); pred=_pred(row); ok=pred==row["actual_observed_behavior"]; label,color=colors[condition]
            lanes.append(f'<div class="tr-lane {"ok" if ok else "fail"}" style="--tone:{color}"><label>{label}</label><span>{_text(pred)}</span><em>{"✓" if ok else "✕"}</em></div>')
        cards.append(f'<div class="tr-case"><b>{sample}</b><p>{_text(texts[sample])}</p>{"".join(lanes)}</div>')
    return "".join(cards)


def render_transfer_lab(cutoff=DEFAULT_TRANSFER_CUTOFF):
    result,dataset=_load(); cutoff=cutoff if cutoff in {"E1","E2","E3","E4"} else DEFAULT_TRANSFER_CUTOFF; metrics=result["metrics"]; passed=sum(result["transfer_hypothesis_checks"].values()); resources=result["resources"]
    nodes=[]
    for condition in TRANSFER:
        label,color=TRANSFER[condition]; m=metrics[condition]; detail="Ren history + Ren parameters" if condition=="REN_ZERO_SHOT" else "Ren history + Mira parameters" if condition=="MIRA_PARAMETER_SWAP" else "Mira history + Mira parameters"
        nodes.append(f'<div class="tr-node" style="--tone:{color}"><b>{label}</b><strong>{m["top1_accuracy"]:.2%}</strong><span>{detail}<br>Brier {m["brier_score"]:.3f} · NLL {m["negative_log_likelihood"]:.3f}</span></div>')
    base="".join(f'<div class="tr-base" style="--tone:{color}"><b>{label}</b><strong>{metrics[name]["top1_accuracy"]:.1%}</strong><span>Brier {metrics[name]["brier_score"]:.3f} · NLL {metrics[name]["negative_log_likelihood"]:.3f}</span></div>' for name,(label,color) in BASELINES.items())
    roll="".join(f'<div class="tr-cut" style="--tone:{"#34d399" if m["top1_accuracy"]>=.75 else "#fb7185"}"><b>{name}</b><strong>{m["top1_accuracy"]:.0%}</strong><span>NLL {m["negative_log_likelihood"]:.3f}</span></div>' for name,m in result["rolling_metrics"].items())
    core="".join(f'<div><b>✓ {_text(Path(path).name)}</b><span>person branches 0 · {sha[:8]}</span></div>' for path,sha in result["core_logic_hashes"].items())
    return '<section class="tr-lab"><header class="tr-hero"><div><div class="tr-kicker">M9 / M9.1 · SECOND-PERSON TRANSFER</div><h1 class="tr-title">同一套核心確實能換人，但「加入第二人的歷史」沒有讓預測更好</h1><p class="tr-sub">從直播協作者 Synthetic Ren 換到研究協調者 Synthetic Mira。核心 schema、memory、state、transition、predictor、rolling code 一行不改；只替換 person parameters、history 與 fit artifacts，再和 B4/B5 比。</p></div>'+f'<div class="tr-stamps"><div class="tr-stamp"><b>{passed} / 7 HYPOTHESES</b><span>predictive transfer · failed</span></div><div class="tr-stamp ok"><b>0 CORE BRANCHES</b><span>engineering transfer · pass</span></div></div></header><div class="tr-body"><div class="tr-flow">{nodes[0]}<div class="tr-arrow">→</div>{nodes[1]}<div class="tr-arrow">→</div>{nodes[2]}</div><div class="tr-label">STRONG BASELINE FLOOR VS FULL-ADAPT ROLLING WINDOWS</div><div class="tr-grid"><div class="tr-panel"><div class="tr-baselines">{base}</div><p style="color:#fda4af;font-size:8px;line-height:1.5;margin:10px 0 0">B4/B5 都是 75%；Full Adapt 只有 43.75%，Brier 1.050。Top-3 100% 只表示答案仍在候選內，不代表機率正確。</p></div><div class="tr-panel"><div class="tr-roll">{roll}</div><p style="color:#94a3b8;font-size:8px;line-height:1.5;margin:10px 0 0">E1 0% → E3 100%：同一個適配模型跨 cutoff 仍高度不穩定。</p></div></div><div class="tr-label">SELECTED MIRA CUTOFF · '+cutoff+' · B4 / B5 / ZERO-SHOT / PARAM / FULL</div><div class="tr-cases">'+_cases(result,dataset,cutoff)+'</div><div class="tr-label">UNCHANGED CORE · SAME SHA-BOUND FILES, ZERO PERSON-ID BRANCHES</div><div class="tr-core">'+core+'</div><div class="tr-boundary"><div style="--tone:#34d399"><b>真的完成</b><span>第二人新資料、三 transfer arms、B0–B5、strict cutoff、108 calls、核心 SHA／branch audit、失敗保存。</span></div>'+f'<div style="--tone:#fbbf24"><b>成本與 parser</b><span>{resources["total_model_calls"]} calls · {resources["prompt_tokens"]+resources["completion_tokens"]:,} tokens · {resources["model_latency_seconds"]:.1f}s。第一次 M9 failure 保留；M9.1 有 3 次 summary-key alias。</span></div><div style="--tone:#fb7185"><b>不能宣稱</b><span>適配歷史有效、已泛化真人、已預測 Uruha、或通用人類模型。下一步 M10：language/persona/human/runtime。</span></div></div></div></section>'
